def validate(args, output):
    # Re-simulate a reference RandomizedSet; insert/remove must match and
    # getRandom must return a value currently in the set.
    ops = ["RandomizedSet","insert","remove","insert","getRandom",
           "remove","insert","getRandom"]
    call = [[],[1],[2],[2],[],[1],[2],[]]
    s = set()
    for i,(op,a) in enumerate(zip(ops,call)):
        o = output[i]
        if op == 'RandomizedSet':
            if o is not None: return False
        elif op == 'insert':
            exp = a[0] not in s; s.add(a[0])
            if o != exp: return False
        elif op == 'remove':
            exp = a[0] in s; s.discard(a[0])
            if o != exp: return False
        elif op == 'getRandom':
            if o not in s: return False
    return True

solutions.naive:
import random

class RandomizedSet:
    def __init__(self):
        self.values = []

    def insert(self, val: int) -> bool:
        if val in self.values:
            return False
        self.values.append(val)
        return True

    def remove(self, val: int) -> bool:
        if val not in self.values:
            return False
        self.values.remove(val)
        return True

    def getRandom(self) -> int:
        return random.choice(self.values)

